normal.sql:
SELECT id, name, price
FROM products
WHERE id = $1;

SELECT id, status, total FROM orders
WHERE customer_id = $1
ORDER BY created_at DESC LIMIT 20;

incident.sql:
SELECT id, status, total FROM orders
WHERE customer_id::text = $1::text
ORDER BY created_at DESC LIMIT 20;

indexed.sql:
SELECT id, status, total FROM orders
WHERE customer_id::text = $1::text
